import { Component, OnInit, OnDestroy, signal, ViewChild } from '@angular/core';
import { Router } from '@angular/router';
import { CalendarService } from '../../../services/calendar.service';
import { TranslationService } from '../../../services/translation.service';
import { LangService } from '../../../services/lang.service';
import { 
  CalendarEvent, 
  EventType, 
  EventStatus, 
  CalendarFilters,
  SimpleEvent 
} from '../../../models/calendar.model';
import { Subscription } from 'rxjs';

@Component({
  selector: 'app-system-calendar',
  standalone: false,
  templateUrl: './system-calendar.component.html',
  styleUrls: ['./system-calendar.component.css']
})
export class SystemCalendarComponent implements OnInit, OnDestroy {
  // Signals for reactive state management
  systemEvents = signal<CalendarEvent[]>([]);
  simpleEvents = signal<SimpleEvent[]>([]);
  filteredEvents = signal<CalendarEvent[]>([]);
  currentDate = signal<Date>(new Date());
  selectedDate = signal<Date | null>(null);
  loading = signal<boolean>(false);
  error = signal<string | null>(null);
  isRTL = signal<boolean>(false);
  // UI density
  compact = signal<boolean>(false);
  // Font size toggle (small vs normal)
  fontSmall = signal<boolean>(false);

  // Filter state
  filters = signal<CalendarFilters>({});

  // Calendar view state
  viewMode = signal<'month' | 'week' | 'day'>('month');
  displayMode = signal<'calendar' | 'table'>('calendar');
  showAllSystemEventsModal = signal<boolean>(false);

  // Calendar data
  calendarDays: Date[] = [];
  weekDays: string[] = [];
  monthNames: string[] = [];

  private subscriptions: Subscription[] = [];

  constructor(
    private calendarService: CalendarService,
    private translationService: TranslationService,
    private langService: LangService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.initializeCalendar();
    this.loadSystemEvents();
    this.setupLanguageSubscription();
    // restore preferences
    try {
      const saved = localStorage.getItem('systemCalendar.compact');
      if (saved === '1') {
        this.compact.set(true);
      }
      const savedFont = localStorage.getItem('systemCalendar.fontSmall');
      if (savedFont === '1') {
        this.fontSmall.set(true);
      }
    } catch {}

    // default to compact and small font on first load for < 1400px if no saved preference
    try {
      const hasCompactPref = localStorage.getItem('systemCalendar.compact') !== null;
      const hasFontPref = localStorage.getItem('systemCalendar.fontSmall') !== null;
      if (window && window.innerWidth < 1400) {
        if (!hasCompactPref) {
          this.compact.set(true);
        }
        if (!hasFontPref) {
          this.fontSmall.set(true);
        }
      }
    } catch {}
  }

  ngOnDestroy(): void {
    this.subscriptions.forEach(sub => sub.unsubscribe());
  }

  toggleCompact(): void {
    const next = !this.compact();
    this.compact.set(next);
    try {
      localStorage.setItem('systemCalendar.compact', next ? '1' : '0');
    } catch {}
  }

  toggleFontSize(): void {
    const next = !this.fontSmall();
    this.fontSmall.set(next);
    try {
      localStorage.setItem('systemCalendar.fontSmall', next ? '1' : '0');
    } catch {}
  }

  private initializeCalendar(): void {
    this.generateCalendarDays();
    this.setupWeekDays();
    this.setupMonthNames();
  }

  private setupLanguageSubscription(): void {
    const langSub = this.langService.currentLang$.subscribe((lang: 'ar' | 'en') => {
      this.isRTL.set(lang === 'ar');
      this.setupWeekDays();
      this.setupMonthNames();
    });
    this.subscriptions.push(langSub);
  }

  private setupWeekDays(): void {
    if (this.isRTL()) {
      this.weekDays = ['الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت'];
    } else {
      this.weekDays = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    }
  }

  private setupMonthNames(): void {
    if (this.isRTL()) {
      this.monthNames = [
        'يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو',
        'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'
      ];
    } else {
      this.monthNames = [
        'January', 'February', 'March', 'April', 'May', 'June',
        'July', 'August', 'September', 'October', 'November', 'December'
      ];
    }
  }

  private generateCalendarDays(): void {
    const current = this.currentDate();
    const year = current.getFullYear();
    const month = current.getMonth();
    const day = current.getDate();
    
    this.calendarDays = [];
    
    if (this.viewMode() === 'month') {
      // Get first day of month and calculate starting point
      const firstDay = new Date(year, month, 1);
      const lastDay = new Date(year, month + 1, 0);
      const startDate = new Date(firstDay);
      
      // Adjust start date to beginning of week
      const dayOfWeek = firstDay.getDay();
      startDate.setDate(startDate.getDate() - dayOfWeek);
      
      const endDate = new Date(lastDay);
      endDate.setDate(endDate.getDate() + (6 - lastDay.getDay()));
      
      for (let d = new Date(startDate); d <= endDate; d.setDate(d.getDate() + 1)) {
        this.calendarDays.push(new Date(d));
      }
    } else if (this.viewMode() === 'week') {
      // Get start of week (Sunday)
      const startOfWeek = new Date(current);
      const dayOfWeek = current.getDay();
      startOfWeek.setDate(current.getDate() - dayOfWeek);
      
      // Generate 7 days for the week
      for (let i = 0; i < 7; i++) {
        const day = new Date(startOfWeek);
        day.setDate(startOfWeek.getDate() + i);
        this.calendarDays.push(day);
      }
    } else if (this.viewMode() === 'day') {
      // Show only the selected day
      this.calendarDays.push(new Date(current));
    }
  }

  loadSystemEvents(): void {
    this.loading.set(true);
    this.error.set(null);

    // Load both regular events for calendar view and simple events for table view
    const loadRegularEvents = this.calendarService.getSystemEvents(
      this.filters().type,
      this.filters().status
    );

    const loadSimpleEvents = this.calendarService.getSystemEventsSimple();

    // Load regular events for calendar view
    const regularEventsSub = loadRegularEvents.subscribe({
      next: (response) => {
        if (response.success) {
          // Assign colors based on event type
          const eventsWithColors = response.data.map(event => ({
            ...event,
            color: this.getEventTypeColor(event.type)
          }));
          this.systemEvents.set(eventsWithColors);
          this.updateFilteredEvents();
        }
      },
      error: (error) => {
        console.error('Error loading system events:', error);
        this.error.set('Failed to load system events');
      }
    });

    // Load simple events for table view
    const simpleEventsSub = loadSimpleEvents.subscribe({
      next: (response) => {
        if (response.success) {
          this.simpleEvents.set(response.data.events);
        }
        this.loading.set(false);
      },
      error: (error) => {
        console.error('Error loading simple system events:', error);
        // Don't set error for simple events as it's optional for table view
        this.loading.set(false);
      }
    });

    this.subscriptions.push(regularEventsSub, simpleEventsSub);
  }

  private updateFilteredEvents(): void {
    let filtered = this.systemEvents();

    // Apply type filter
    if (this.filters().type !== undefined) {
      filtered = filtered.filter(event => event.type === this.filters().type);
    }

    // Apply status filter
    if (this.filters().status !== undefined) {
      filtered = filtered.filter(event => event.status === this.filters().status);
    }

    this.filteredEvents.set(filtered);
  }

  // Navigation methods
  previousMonth(): void {
    const current = this.currentDate();
    current.setMonth(current.getMonth() - 1);
    this.currentDate.set(new Date(current));
    this.generateCalendarDays();
  }

  nextMonth(): void {
    const current = this.currentDate();
    current.setMonth(current.getMonth() + 1);
    this.currentDate.set(new Date(current));
    this.generateCalendarDays();
  }

  goToToday(): void {
    this.currentDate.set(new Date());
    this.generateCalendarDays();
  }

  // Event handling
  onDateClick(date: Date): void {
    this.selectedDate.set(date);
  }

  onFilterChange(filters: CalendarFilters): void {
    this.filters.set(filters);
    this.loadSystemEvents();
  }

  onTypeFilterChange(value: string): void {
    const newFilters = { ...this.filters() };
    newFilters.type = value ? +value : undefined;
    this.onFilterChange(newFilters);
  }

  onStatusFilterChange(value: string): void {
    const newFilters = { ...this.filters() };
    newFilters.status = value ? +value : undefined;
    this.onFilterChange(newFilters);
  }

  retryLoadEvents(): void {
    this.loadSystemEvents();
  }

  onViewModeChange(mode: any): void {
    this.viewMode.set(mode as 'month' | 'week' | 'day');
    // Regenerate calendar days based on view mode
    this.generateCalendarDays();
  }

  onDisplayModeChange(mode: 'calendar' | 'table'): void {
    this.displayMode.set(mode);
  }

  viewAllSystemEvents(event: Event): void {
    
    // Prevent default behavior and stop propagation
    event.preventDefault();
    event.stopPropagation();
    
    // Open the modal to show all system events
    this.showAllSystemEventsModal.set(true);
    
  }

  closeAllSystemEventsModal(): void {
    this.showAllSystemEventsModal.set(false);
  }

  // Helper methods
  private formatDateForComparison(date: Date): string {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  }

  getEventsForDate(date: Date): CalendarEvent[] {
    const dateStr = this.formatDateForComparison(date);
    return this.filteredEvents().filter(event => {
      const eventDate = this.formatDateForComparison(new Date(event.startDate));
      return eventDate === dateStr;
    });
  }

  isToday(date: Date): boolean {
    const today = new Date();
    return date.toDateString() === today.toDateString();
  }

  isSelectedDate(date: Date): boolean {
    const selected = this.selectedDate();
    return selected ? date.toDateString() === selected.toDateString() : false;
  }

  isCurrentMonth(date: Date): boolean {
    const current = this.currentDate();
    return date.getMonth() === current.getMonth() && date.getFullYear() === current.getFullYear();
  }

  getDayName(date: Date): string {
    if (this.isRTL()) {
      const dayNames = ['الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت'];
      return dayNames[date.getDay()];
    } else {
      const dayNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
      return dayNames[date.getDay()];
    }
  }

  getTodayDate(): string {
    const today = new Date();
    return today.toLocaleDateString('en-US', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  }

  getEventTypeLabel(type: EventType): string {
    const key = this.calendarService.getEventTypeLabel(type);
    return this.translate(key);
  }

  getEventStatusLabel(status: EventStatus): string {
    const key = this.calendarService.getEventStatusLabel(status);
    return this.translate(key);
  }

  getEventStatusColor(status: EventStatus): string {
    return this.calendarService.getEventStatusColor(status);
  }

  getPriorityColor(priority: number): string {
    return this.calendarService.getPriorityColor(priority);
  }

  getPriorityLabel(priority: number): string {
    switch (priority) {
      case 1:
        return this.translate('calendar.priority.high');
      case 2:
        return this.translate('calendar.priority.medium');
      case 3:
        return this.translate('calendar.priority.low');
      default:
        return this.translate('calendar.priority.normal');
    }
  }

  formatEventDateTime(dateString: string): string {
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  getEventTypeColor(type: EventType): string {
    return this.calendarService.getEventTypeColor(type);
  }

  translate(key: string): string {
    return this.translationService.translate(key);
  }


  getEventTypeFromName(typeName: string): EventType {
    const typeMap: { [key: string]: EventType } = {
      'اجتماع': EventType.Meeting,
      'مهمة': EventType.Task,
      'زيارة': EventType.Visit,
      'سفر': EventType.Travel,
      'meeting': EventType.Meeting,
      'task': EventType.Task,
      'visit': EventType.Visit,
      'travel': EventType.Travel,
      'Meeting': EventType.Meeting,
      'Task': EventType.Task,
      'Visit': EventType.Visit,
      'Travel': EventType.Travel
    };
    return typeMap[typeName] || EventType.Meeting;
  }

  // Navigate to event details page based on event type
  navigateToEventDetails(event: CalendarEvent): void {
    const eventType = event.eventTypeName;
    const entityId = event.originalEntityId;

    switch (eventType) {
      case EventType.Meeting:
        this.router.navigate(['/meetings/details', entityId]);
        break;
      case EventType.Task:
        this.router.navigate(['/tasks/details', entityId]);
        break;
      case EventType.Visit:
        this.router.navigate(['/visits/details', entityId]);
        break;
      case EventType.Travel:
        this.router.navigate(['/travel/details', entityId]);
        break;
      default:
        console.warn('Unknown event type:', eventType);
    }
  }

  // Navigate to simple event details page
  navigateToSimpleEventDetails(event: SimpleEvent): void {
    const eventType = this.getEventTypeFromName(event.eventTypeName);
    const entityId = event.originalEntityId;

    switch (eventType) {
      case EventType.Meeting:
        this.router.navigate(['/meetings/details', entityId]);
        break;
      case EventType.Task:
        this.router.navigate(['/tasks/details', entityId]);
        break;
      case EventType.Visit:
        this.router.navigate(['/visits/details', entityId]);
        break;
      case EventType.Travel:
        this.router.navigate(['/travel/details', entityId]);
        break;
      default:
        console.warn('Unknown event type:', eventType);
    }
  }

  // Enum getters for template
  get EventType() {
    return EventType;
  }

  get EventStatus() {
    return EventStatus;
  }
}
